sys_script_include.script:
var HSBC_Retry_Outbound = Class.create();
HSBC_Retry_Outbound.prototype = {
    initialize: function() {},
	//checkEnvironment() checks outbound HTTP log table and returns true if there are records with error codes:204,429,500,401,0
    checkEnvironment: function() {
        var interval = gs.getProperty("x_hsb11_hsbc_mss_o.retry_interval_environment_check");
        var url_gcp = gs.getProperty("x_hsb11_hsbc_mss_o.eventOutbound_GCP_uri_payload");
        var url_hss = gs.getProperty("x_hsb11_hsbc_mss_o.eventOutbound_uri");
        var gr = new GlideRecord("sys_outbound_http_log");
        //Added Error Code:204 for MSSRBXCE-439,401 for MSSRBXCE-578,0 for MSSRBXCE-582
        gr.addQuery('response_status', 'IN', '204,429,500,401,0');
        gr.addEncodedQuery(interval);
        gr.addQuery('url', 'IN', url_gcp + ',' + url_hss);
        gr.query();
        //MSSRBXCE-439 Swapped true and false 
        if (gr.hasNext())
            return true;
        else
            return false;
    },
	//retry() checks records of MSS Event Outbound table and performs retry if applicable
    retry: function() {
        var retry_cnt = gs.getProperty("x_hsb11_hsbc_mss_o.event_outbound_retry_count");
        var gr = new GlideRecord("x_hsb11_hsbc_mss_o_mss_event_outbound");
        gr.addQuery("state", "Error");
        gr.addQuery("retry_count", "<", retry_cnt);
        gr.addEncodedQuery("sys_created_on>=javascript:gs.beginningOfYesterday()");
        gr.query();
        while (gr.next()) {
            gr.state = "Ready to be sent";
            gr.update();
        }
    },
	//regenerateGCPToken() regenerates the token by executing a scheduled job for error code:401
    regenerateGCPToken: function() {
        //MSSRBXCE-578
        if (gs.getProperty("x_hsb11_hsbc_mss_o.eventOutbound_GCP_HSS") == "GCP") {
            var retry_cnt = gs.getProperty("x_hsb11_hsbc_mss_o.event_outbound_retry_count");
            var gr = new GlideRecord("x_hsb11_hsbc_mss_o_mss_event_outbound");
            gr.addQuery("state", "Error");
            gr.addQuery("error_code", "401");
            gr.addQuery("retry_count", "<", retry_cnt);
            gr.addEncodedQuery("sys_created_on>=javascript:gs.beginningOfYesterday()");
            gr.query();
            if (gr.next()) {
                var jobId = gs.getProperty('x_hsb11_hsbc_mss_o.eventOutbound_GCP_token_refresh_job'); //HSBC MSS EL GCP Token Refresh
                var obj = new GlideRecord('sysauto_script');
				obj.get(jobId);
                gs.executeNow(obj);
                var endSleep = new GlideDuration().getNumericValue() + 10000;
                while (new GlideDuration().getNumericValue() < endSleep) {
                    //wait 
                }
            }
        }
    },
    type: 'HSBC_Retry_Outbound'
};
